                else{ // tricky decoding

                    v = 0;

                    switch(C){

                    case -1: // code 0 -> 1, 1 -> 0

                        if(B < 2)

                            v = get_bits1(gb) ^ 1;

                        break;

                    case  0:

                    case  2: // code 0 -> 2, 1 -> 0

                        v = (get_bits1(gb) ^ 1) << 1;

